def first_or(xs: list[int], default: int) -> int:
    """Return the first element of xs, or default if xs is empty."""
    if xs:
        return xs[0]
    return default


def test_first_or_nonempty() -> None:
    assert first_or([7, 8, 9], 0) == 7
    assert first_or([5], 99) == 5


def test_first_or_empty() -> None:
    assert first_or([], 42) == 42
    assert first_or([], -1) == -1


def test_first_or_falsy_first_element() -> None:
    assert first_or([0, 1], 5) == 0
    assert first_or([0], 5) == 0


def test_first_or_negative_values() -> None:
    assert first_or([-3, 2], 10) == -3


def test_first_or_does_not_mutate() -> None:
    xs = [1, 2, 3]
    first_or(xs, 0)
    assert xs == [1, 2, 3]
